import { useLayoutEffect, useMemo, useState, type ReactNode } from 'react'
import {
  Activity, AlertTriangle, ArrowRight, BadgeCheck, Banknote, BedDouble, Bell,
  Bot, Boxes, CalendarDays, Camera, Check, CheckCircle2, ChevronDown,
  ChevronLeft, ChevronRight, CircleDollarSign, ClipboardCheck, Clock3,
  Droplets, FileCheck2, Gauge, HeartHandshake, Home, ImagePlus,
  LayoutDashboard, LockKeyhole, MapPin, MessageCircle,
  ReceiptText, RefreshCcw, Search, Send, ShieldCheck, ShoppingBag, Sparkles,
  Star, ThermometerSun, TrendingUp, Users, WalletCards, Wifi, X,
} from 'lucide-react'
import propertyImage from '../cascade-stay.jpg'

type Product = 'dashboard' | 'cleaner' | 'booking'
type DashboardView = 'overview' | 'analytics' | 'bookings' | 'finance' | 'guests' | 'turnovers' | 'inventory' | 'health'

const navigation: Array<{ id: DashboardView; label: string; icon: typeof LayoutDashboard; badge?: string; finance?: boolean }> = [
  { id: 'overview', label: 'Command center', icon: LayoutDashboard },
  { id: 'analytics', label: 'Analytics', icon: TrendingUp, finance: true },
  { id: 'bookings', label: 'Bookings & stays', icon: CalendarDays, badge: '3' },
  { id: 'finance', label: 'Finance review', icon: WalletCards, badge: '2', finance: true },
  { id: 'guests', label: 'Guest relationships', icon: Users },
  { id: 'turnovers', label: 'Turnovers', icon: ClipboardCheck, badge: '1' },
  { id: 'inventory', label: 'Inventory', icon: Boxes, badge: '2' },
  { id: 'health', label: 'System health', icon: Activity },
]

function Mark() {
  return <span className="suite-mark" aria-hidden="true"><span></span><span></span><span></span></span>
}

function SuiteHeader({ product, onProduct }: { product: Product; onProduct: (product: Product) => void }) {
  return <header className="suite-header"><a className="suite-brand" href="#top"><Mark /><span><b>Cascade Hideaway</b><small>Experience design concept</small></span></a><nav aria-label="Mockup suite"><button className={product === 'dashboard' ? 'active' : ''} onClick={() => onProduct('dashboard')}><LayoutDashboard size={15} />Command center</button><button className={product === 'cleaner' ? 'active' : ''} onClick={() => onProduct('cleaner')}><ClipboardCheck size={15} />Cleaner flow</button><button className={product === 'booking' ? 'active' : ''} onClick={() => onProduct('booking')}><BedDouble size={15} />Direct booking</button></nav><span className="sample-note"><Sparkles size={13} />Sample data · no live actions</span></header>
}

function Pill({ tone = 'neutral', children }: { tone?: 'neutral' | 'good' | 'warn' | 'danger' | 'gold'; children: ReactNode }) {
  return <span className={`pill ${tone}`}>{children}</span>
}

function Metric({ label, value, meta, icon: Icon, tone = 'ink' }: { label: string; value: string; meta: string; icon: typeof TrendingUp; tone?: string }) {
  return <article className="metric"><div><span>{label}</span><strong className={tone}>{value}</strong><small>{meta}</small></div><Icon size={18} /></article>
}

function Panel({ eyebrow, title, action, children, className = '' }: { eyebrow?: string; title: string; action?: ReactNode; children: ReactNode; className?: string }) {
  return <article className={`panel ${className}`}><div className="panel-heading"><div>{eyebrow && <span className="eyebrow">{eyebrow}</span>}<h2>{title}</h2></div>{action}</div>{children}</article>
}

function Row({ icon: Icon, title, detail, side, tone = 'neutral' }: { icon: typeof CalendarDays; title: string; detail: string; side?: ReactNode; tone?: 'neutral' | 'good' | 'warn' | 'danger' }) {
  return <div className="data-row"><span className={`row-icon ${tone}`}><Icon size={17} /></span><div><b>{title}</b><small>{detail}</small></div>{side && <div className="row-side">{side}</div>}<ChevronRight size={17} className="row-arrow" /></div>
}

function OutlookChart() {
  return <div className="outlook-chart"><div className="outlook-summary"><div><span>Recognized revenue</span><b>₱61,200</b><small>1–15 Aug · actual</small></div><div><span>Expected revenue</span><b>₱78,600</b><small>16–31 Aug · booked + held</small></div><Pill tone="good">+28% outlook</Pill></div><div className="outlook-legend"><span><i className="actual-key"></i>Actual</span><span><i className="forecast-key"></i>Forecast</span><span><i className="range-key"></i>Likely range</span></div><div className="chart outlook-plot"><div className="chart-y"><span>₱160k</span><span>₱120k</span><span>₱80k</span><span>₱40k</span></div><svg viewBox="0 0 760 220" role="img" aria-label="Thirty-day net revenue outlook: actual revenue through 15 August, forecast from 16 through 31 August, with likely range."><path className="chart-grid" d="M0 28H760M0 88H760M0 148H760M0 208H760" /><path className="forecast-range" d="M380 110 C425 101 450 94 500 100 S570 74 625 58 S700 45 760 50 L760 22 C708 12 670 18 625 32 S548 46 500 72 S430 72 380 83Z" /><path className="actual-area" d="M0 170 C55 162 90 166 132 145 S205 120 252 109 S320 119 380 83 V208H0Z" /><path className="actual-line" d="M0 170 C55 162 90 166 132 145 S205 120 252 109 S320 119 380 83" /><path className="forecast-line" d="M380 83 C425 72 450 68 500 72 S570 46 625 32 S700 12 760 22" /><line className="today-line" x1="380" y1="18" x2="380" y2="208" /><circle className="today-dot" cx="380" cy="83" r="6" /><text className="today-label" x="391" y="34">TODAY · AUG 15</text></svg><div className="chart-x outlook-x"><span>Aug 1</span><span>Aug 8</span><span className="actual-end">Aug 15<br /><b>Actual to here</b></span><span>Aug 22</span><span>Aug 31</span></div></div><p className="outlook-note"><TrendingUp size={14} />Forecast combines confirmed bookings with payment-held dates. The shaded band shows the likely result if pending payments do not clear.</p></div>
}

function DashboardOverview({ setView }: { setView: (view: DashboardView) => void }) {
  return <><section className="dash-title"><div><span className="eyebrow">Sunday · 31 August</span><h1>Good morning, Lloyd</h1><p>One property, one decision queue. Here is what needs attention today.</p></div><div className="title-actions"><button className="secondary"><RefreshCcw size={15} />Synced 2m ago</button><button className="primary" onClick={() => setView('bookings')}>Review priorities <ArrowRight size={16} /></button></div></section><section className="attention-banner"><span><AlertTriangle size={22} /></span><div><b>3 decisions need your attention</b><small>2 payment reviews · 1 turnover exception · no calendar conflicts</small></div><button onClick={() => setView('finance')}>Open queue <ArrowRight size={15} /></button></section><section className="metric-grid"><Metric label="Occupancy" value="78%" meta="23 of 30 nights" icon={BedDouble} tone="forest" /><Metric label="Net revenue" value="₱187,810" meta="Year to date" icon={TrendingUp} tone="ink" /><Metric label="ADR" value="₱2,840" meta="Average daily rate" icon={CircleDollarSign} tone="gold" /><Metric label="RevPAR" value="₱2,215" meta="Revenue per available night" icon={Gauge} tone="forest" /></section><section className="dash-two"><Panel eyebrow="Live operations" title="Today at Cascade" action={<button className="text-button" onClick={() => setView('bookings')}>Full calendar <ArrowRight size={14} /></button>}><div className="timeline"><Row icon={CheckCircle2} title="Cleaner arrival window" detail="Turnover · checkout completed" tone="good" side={<time>08:30</time>} /><Row icon={BedDouble} title="Guest checkout" detail="Airbnb · access expires after inspection" tone="neutral" side={<time>11:00</time>} /><Row icon={ClipboardCheck} title="Turnover evidence due" detail="Photos, water and electric readings" tone="warn" side={<time>14:00</time>} /><Row icon={CalendarDays} title="Direct guest arrival" detail="Guide and arrival advisory scheduled" tone="neutral" side={<time>15:00</time>} /></div><div className="next-stay"><span>SEP<br /><b>05</b></span><div><small>Next arrival</small><b>Direct booking · 3 nights</b><em>Guide scheduled · access pending final review</em></div><Pill tone="good">4 days</Pill></div></Panel><Panel eyebrow="Owner decisions" title="Decision queue" action={<Pill tone="gold">3 open</Pill>}><div className="decision-list"><Row icon={ReceiptText} title="Payment evidence ready" detail="CH-0831-04 · receipt and bank email agree" tone="good" side={<><b>₱4,500</b><small>Review</small></>} /><Row icon={ClipboardCheck} title="Turnover evidence incomplete" detail="Bathroom wide-angle photo is still missing" tone="warn" side={<><b>14:00</b><small>Follow up</small></>} /><Row icon={Boxes} title="Restock before next arrival" detail="Water and coffee fall below forecast demand" tone="danger" side={<><b>2 items</b><small>Build list</small></>} /></div><p className="authority-note"><LockKeyhole size={15} />High-risk actions require named approval and are recorded in the audit trail.</p></Panel></section><section className="dash-two lower"><Panel eyebrow="Forward view" title="30-day business outlook"><div className="chart"><div className="chart-y"><span>₱120k</span><span>₱80k</span><span>₱40k</span><span>₱0</span></div><svg viewBox="0 0 760 220" role="img" aria-label="Sample net revenue outlook"><path className="chart-grid" d="M0 28H760M0 88H760M0 148H760M0 208H760" /><path className="chart-area" d="M0 184C62 174 86 181 132 156s86-20 130-38 86 7 133-25 79-52 128-35 71 25 112-3 74-46 125-31v184H0Z" /><path className="chart-line" d="M0 184C62 174 86 181 132 156s86-20 130-38 86 7 133-25 79-52 128-35 71 25 112-3 74-46 125-31" /><circle cx="395" cy="94" r="5" /><circle cx="660" cy="23" r="5" /></svg><div className="chart-x"><span>Aug 1</span><span>Aug 8</span><span>Aug 15</span><span>Aug 22</span><span>Aug 31</span></div></div></Panel><Panel eyebrow="Arrival assurance" title="Property readiness"><div className="readiness"><div className="ring"><b>86%</b><small>4 of 5 ready</small></div><ul><li><Check size={15} />Calendar conflict check</li><li><Check size={15} />Guest guide scheduled</li><li><Check size={15} />Access preparation</li><li><Check size={15} />Core inventory</li><li className="warn"><Clock3 size={15} />Turnover evidence</li></ul></div></Panel></section></>
}

