  return <><section className="dash-title"><div><span className="eyebrow">Sunday · 31 August</span><h1>Good morning, Lloyd</h1><p>One property, one decision queue. Here is what needs attention today.</p></div><div className="title-actions"><button className="secondary"><RefreshCcw size={15} />Synced 2m ago</button><button className="primary" onClick={() => setView('bookings')}>Review priorities <ArrowRight size={16} /></button></div></section><section className="attention-banner"><span><AlertTriangle size={22} /></span><div><b>3 decisions need your attention</b><small>2 payment reviews · 1 turnover exception · no calendar conflicts</small></div><button onClick={() => setView('finance')}>Open queue <ArrowRight size={15} /></button></section><section className="metric-grid"><Metric label="Occupancy" value="78%" meta="23 of 30 nights" icon={BedDouble} tone="forest" /><Metric label="Net revenue" value="₱187,810" meta="Year to date" icon={TrendingUp} tone="ink" /><Metric label="ADR" value="₱2,840" meta="Average daily rate" icon={CircleDollarSign} tone="gold" /><Metric label="RevPAR" value="₱2,215" meta="Revenue per available night" icon={Gauge} tone="forest" /></section><section className="dash-two"><Panel eyebrow="Live operations" title="Today at Cascade" action={<button className="text-button" onClick={() => setView('bookings')}>Full calendar <ArrowRight size={14} /></button>}><div className="timeline"><Row icon={CheckCircle2} title="Cleaner arrival window" detail="Turnover · checkout completed" tone="good" side={<time>08:30</time>} /><Row icon={BedDouble} title="Guest checkout" detail="Airbnb · access expires after inspection" tone="neutral" side={<time>11:00</time>} /><Row icon={ClipboardCheck} title="Turnover evidence due" detail="Photos, water and electric readings" tone="warn" side={<time>14:00</time>} /><Row icon={CalendarDays} title="Direct guest arrival" detail="Guide and arrival advisory scheduled" tone="neutral" side={<time>15:00</time>} /></div><div className="next-stay"><span>SEP<br /><b>05</b></span><div><small>Next arrival</small><b>Direct booking · 3 nights</b><em>Guide scheduled · access pending final review</em></div><Pill tone="good">4 days</Pill></div></Panel><Panel eyebrow="Owner decisions" title="Decision queue" action={<Pill tone="gold">3 open</Pill>}><div className="decision-list"><Row icon={ReceiptText} title="Payment evidence ready" detail="CH-0831-04 · receipt and bank email agree" tone="good" side={<><b>₱4,500</b><small>Review</small></>} /><Row icon={ClipboardCheck} title="Turnover evidence incomplete" detail="Bathroom wide-angle photo is still missing" tone="warn" side={<><b>14:00</b><small>Follow up</small></>} /><Row icon={Boxes} title="Restock before next arrival" detail="Water and coffee fall below forecast demand" tone="danger" side={<><b>2 items</b><small>Build list</small></>} /></div><p className="authority-note"><LockKeyhole size={15} />High-risk actions require named approval and are recorded in the audit trail.</p></Panel></section><section className="dash-two lower"><Panel eyebrow="Forward view" title="30-day business outlook"><OutlookChart /></Panel><Panel eyebrow="Arrival assurance" title="Property readiness"><div className="readiness"><div className="ring"><b>86%</b><small>4 of 5 ready</small></div><ul><li><Check size={15} />Calendar conflict check</li><li><Check size={15} />Guest guide scheduled</li><li><Check size={15} />Access preparation</li><li><Check size={15} />Core inventory</li><li className="warn"><Clock3 size={15} />Turnover evidence</li></ul></div></Panel></section></>
