  const content = { overview: <DashboardOverviewRefined setView={setView} />, analytics: <AnalyticsView />, bookings: <BookingView />, finance: <FinanceView />, guests: <GuestsView />, turnovers: <TurnoversView />, inventory: <InventoryView />, health: <HealthView /> }[displayed]
  return <div className="dashboard-shell"><aside className="dash-sidebar"><div className="dash-brand"><Mark /><span><b>Cascade Hideaway</b><small>Command center</small></span></div><div className="property-switch"><BedDouble size={17} /><span><small>Current property</small><b>Cascade Hideaway</b></span><ChevronDown size={15} /></div><nav aria-label="Dashboard navigation">{navigation.filter((item) => !(ops && item.finance)).map((item) => { const Icon = item.icon; return <button key={item.id} className={displayed === item.id ? 'active' : ''} onClick={() => setView(item.id)}><Icon size={18} /><span>{item.label}</span>{item.badge && <b>{item.badge}</b>}</button> })}</nav><div className="sidebar-health"><span></span><div><b>Systems healthy</b><small>Calendar refreshed 9m ago</small></div></div></aside><div className="dashboard-workspace"><header className="dash-topbar"><button className="search-control"><Search size={17} /><span>Search bookings, guests, tasks…</span><kbd>⌘ K</kbd></button><div className="topbar-actions"><div className="role-toggle" aria-label="Role preview"><button className={!ops ? 'active' : ''} onClick={() => setOps(false)}>Owner</button><button className={ops ? 'active' : ''} onClick={() => setOps(true)}>OPS-safe</button></div><button aria-label="Notifications" className="icon-control"><Bell size={18} /></button><span className="profile">CL</span></div></header><div className="mockup-ribbon"><Sparkles size={13} />Interactive concept · sample data only · live permissions are server enforced</div><main className="dash-main">{ops && <div className="ops-notice"><ShieldCheck size={16} />OPS-safe preview: finance, payment amounts, and guest contact details are removed from this experience.</div>}{content}</main><nav className="dash-mobile-nav" aria-label="Mobile dashboard navigation">{navigation.filter((item) => !(ops && item.finance)).slice(0, 5).map((item) => { const Icon = item.icon; return <button key={item.id} className={displayed === item.id ? 'active' : ''} onClick={() => setView(item.id)}><Icon size={19} /><span>{item.label.split(' ')[0]}</span></button> })}</nav><button className="suite-link" onClick={() => onProduct('booking')}>Preview guest booking journey <ArrowRight size={15} /></button></div></div>
