const cleanerSteps = ['Briefing', 'Evidence', 'Prepare', 'Clean', 'Review']

function CleanerMockup({ onProduct }: { onProduct: (product: Product) => void }) {
  const [phase, setPhase] = useState(0)
  const [items, setItems] = useState<Record<string, boolean>>({ bed: true, linen: true, kitchen: true, bathroom: false, floors: false })
  const complete = Object.values(items).filter(Boolean).length
  const stepContent = useMemo(() => {
    if (phase === 0) return <><div className="cleaner-banner"><Pill tone="gold">Today · 11:00 checkout</Pill><h1>Turnover briefing</h1><p>One stay, one clear handoff. Complete the evidence before the clean.</p><div className="brief-cards"><span><BedDouble size={17} /><b>Cascade Hideaway</b><small>General Santos City</small></span><span><Users size={17} /><b>3 nights</b><small>Last guest: J. Santos</small></span><span><Clock3 size={17} /><b>Due 14:00</b><small>Before next arrival</small></span></div></div><Panel eyebrow="Start safely" title="Before you begin"><Row icon={Wifi} title="Draft protection is active" detail="Your work is saved on this device and retries when a signal returns." tone="good" /><Row icon={CalendarDays} title="Booking details matched" detail="Dates and turnover context are available for this assignment." tone="good" /><button className="primary full" onClick={() => setPhase(1)}>Begin evidence capture <ArrowRight size={16} /></button></Panel></>
    if (phase === 1) return <><div className="cleaner-banner evidence"><Pill tone="warn">Required before cleaning</Pill><h1>Document the starting condition</h1><p>Take clear, wide photos and record both meters. The app compares readings after submission.</p></div><div className="evidence-tiles"><button><Camera size={21} /><b>Pre-clean photos</b><small>5 / 5 uploaded</small><Pill tone="good">Complete</Pill></button><button><Gauge size={21} /><b>Electric meter</b><small>13,842 kWh · photo attached</small><Pill tone="good">Verified</Pill></button><button><Droplets size={21} /><b>Water meter</b><small>37.288 m³ · photo attached</small><Pill tone="good">Verified</Pill></button></div><Panel eyebrow="Readings check" title="Plausibility before you continue"><div className="meter-compare"><span><small>Electric change</small><b>+19 kWh</b><em>Inside expected range</em></span><span><small>Water change</small><b>+0.41 m³</b><em>Inside expected range</em></span></div><p className="helper"><BadgeCheck size={16} />The system checks images and meter movement later; record what you can see and flag uncertainty now.</p><button className="primary full" onClick={() => setPhase(2)}>Evidence complete <ArrowRight size={16} /></button></Panel></>
    if (phase === 2) return <><div className="cleaner-banner prep"><Pill tone="gold">Phase 3 of 5</Pill><h1>Open, inspect, prepare</h1><p>Set the unit up, note concerns, then let chemicals work while you clean the bedroom and kitchen.</p></div><Panel eyebrow="Guided sequence" title="Prepare the unit"><div className="prep-list"><Row icon={Home} title="Open and air the unit" detail="Lights, doors, ventilation, quick visual safety check" tone="good" /><Row icon={ThermometerSun} title="Start chemical dwell timer" detail="Bathroom and kitchen · 10-minute recommended dwell" tone="warn" /><Row icon={AlertTriangle} title="Report a concern immediately" detail="Add a note and photo; do not hide a damage or safety issue." tone="danger" /></div><button className="timer-button"><Clock3 size={18} /><span><small>Chemical dwell timer</small><b>09:42</b></span><span>Running</span></button><button className="primary full" onClick={() => setPhase(3)}>Start room checklist <ArrowRight size={16} /></button></Panel></>
    if (phase === 3) return <><div className="cleaner-banner clean"><Pill tone="gold">{complete} of 5 tasks done</Pill><h1>Clean room by room</h1><p>Tap to confirm each result. If something cannot be completed, flag it—do not mark it done.</p></div><Panel eyebrow="Bedroom & living" title="Work list"><div className="task-list">{[['bed', 'Make bed and refresh linen'], ['linen', 'Check towels, linens, and guest amenities'], ['kitchen', 'Clean kitchen surfaces and utensils'], ['bathroom', 'Disinfect bathroom and restock essentials'], ['floors', 'Vacuum, mop, and final visual sweep']].map(([key, label]) => <button key={key} className={items[key] ? 'checked' : ''} onClick={() => setItems({ ...items, [key]: !items[key] })}><span>{items[key] ? <Check size={17} /> : ''}</span><b>{label}</b><AlertTriangle size={16} className="flag" /></button>)}</div><div className="photo-proof"><ImagePlus size={19} /><div><b>After-clean photos</b><small>2 of 4 required photos captured</small></div><button>Capture</button></div><button className="primary full" disabled={complete < 5} onClick={() => setPhase(4)}>{complete < 5 ? `${5 - complete} task${5 - complete > 1 ? 's' : ''} remaining` : 'Review turnover'} <ArrowRight size={16} /></button></Panel></>
    return <><div className="cleaner-banner review"><Pill tone="good">Ready for review</Pill><h1>Confirm and hand over</h1><p>Review what will be sent. Required evidence is complete; optional notes remain editable.</p></div><Panel eyebrow="Submission summary" title="Turnover evidence"><Row icon={CheckCircle2} title="Checklist complete" detail="38 required tasks, 5 room tasks, and equipment checks recorded" tone="good" side={<Pill tone="good">Pass</Pill>} /><Row icon={Camera} title="Photo evidence" detail="Pre-clean 5 · meter 2 · after-clean 4" tone="good" side={<Pill tone="good">Pass</Pill>} /><Row icon={Gauge} title="Meter readings" detail="Deltas computed from the previous verified turnover" tone="good" side={<Pill tone="good">Plausible</Pill>} /><Row icon={AlertTriangle} title="Reported issues" detail="None declared" tone="good" side={<Pill tone="good">Clear</Pill>} /><div className="submit-boundary"><LockKeyhole size={17} /><p>Submitting sends evidence for verification. A missing item can be rejected automatically; suspicious conditions are escalated for inspection with a human override path.</p></div><button className="primary full submit" onClick={() => setPhase(0)}><Send size={17} />Submit turnover report</button></Panel></>
  }, [phase, items, complete])
  return <div className="cleaner-shell"><header className="cleaner-top"><div><Mark /><span><b>Cascade Care</b><small>Cleaner checklist · draft saved</small></span></div><div><Pill tone="good"><Wifi size={13} />Online</Pill><span className="cleaner-avatar">H</span></div></header><main className="cleaner-main"><div className="cleaner-progress" aria-label={`Phase ${phase + 1} of 5`}>{cleanerSteps.map((step, index) => <button key={step} className={index === phase ? 'active' : index < phase ? 'done' : ''} onClick={() => setPhase(index)}><span>{index < phase ? <Check size={14} /> : index + 1}</span><b>{step}</b></button>)}</div>{stepContent}</main><footer className="cleaner-footer"><button onClick={() => setPhase(Math.max(0, phase - 1))} disabled={phase === 0}><ChevronLeft size={17} />Previous</button><span>Phase {phase + 1} · {cleanerSteps[phase]}</span><button onClick={() => setPhase(Math.min(4, phase + 1))} disabled={phase === 4}>Next<ChevronRight size={17} /></button></footer><button className="suite-link cleaner-link" onClick={() => onProduct('dashboard')}>View operations decision queue <ArrowRight size={15} /></button></div>
}

function BookingMockup({ onProduct }: { onProduct: (product: Product) => void }) {
  const [bookingStep, setBookingStep] = useState(0)
  const [dates, setDates] = useState(false)
  const [menu, setMenu] = useState(false)
  const body = bookingStep === 0 ? <><section className="booking-hero"><img src={propertyImage} alt="A warm, carefully prepared Cascade Hideaway bedroom and living area" /><div className="booking-overlay"></div><header className="guest-nav"><a href="#booking" className="guest-logo"><Mark /><span>Cascade Hideaway</span></a><button className="guest-menu" onClick={() => setMenu(!menu)} aria-expanded={menu}><span>{menu ? <X size={19} /> : <><span></span><span></span></>}</span><b>{menu ? 'Close' : 'Menu'}</b></button><nav className={menu ? 'open' : ''}><a href="#stay">The stay</a><a href="#amenities">Amenities</a><a href="#reviews">Guest notes</a><button onClick={() => setBookingStep(1)}>Check dates</button></nav></header><div className="hero-copy"><Pill tone="gold"><MapPin size={13} />Private stay · General Santos City</Pill><h1>Hotel comfort.<br /><i>Home warmth.</i></h1><p>A calm, private base for stays in General Santos—thoughtfully prepared, clearly priced, and personally hosted.</p><div className="hero-proof"><span><Star size={14} fill="currentColor" />4.98 · 45 Airbnb reviews</span><span>Guest Favorite</span><span>Superhost</span></div></div><div className="hero-book-card" id="booking"><div className="booking-card-top"><span>Book direct</span><b>From ₱1,780 / night</b></div><div className="date-fields"><button onClick={() => setDates(true)}><small>Check-in</small><b>{dates ? 'Sep 5, 2026' : 'Choose date'}</b></button><button onClick={() => setDates(true)}><small>Check-out</small><b>{dates ? 'Sep 8, 2026' : 'Choose date'}</b></button></div>{dates && <div className="availability-result"><CheckCircle2 size={16} /><span><b>Your dates are available</b><small>3 nights · final availability is checked before payment</small></span></div>}<button className="primary booking-cta" onClick={() => { setDates(true); setBookingStep(1) }}>{dates ? 'Continue with these dates' : 'Check availability'} <ArrowRight size={16} /></button><p><ShieldCheck size={14} />No charge until you choose a payment method.</p></div></section><section className="direct-benefit"><div><span className="eyebrow">Why book direct</span><h2>More clarity, less uncertainty.</h2><p>The same home, a direct conversation with the host, and a booking process built around verified availability and payment—not pressure.</p></div><div className="benefit-grid"><span><BadgeCheck size={18} /><b>Best available rate</b><small>Direct booking is priced clearly before you request.</small></span><span><ShieldCheck size={18} /><b>Payment protection</b><small>A receipt is reviewed before a stay is confirmed.</small></span><span><MessageCircle size={18} /><b>Personal support</b><small>Get a real response when your question needs one.</small></span></div></section><section className="stay-section" id="stay"><div className="stay-photo"><img src={propertyImage} alt="Cascade Hideaway interior" /></div><div><span className="eyebrow">A stay made simple</span><h2>Private, restful, and prepared for your arrival.</h2><p>One bedroom, one bed, one bath, and the thoughtful details that make a short stay feel easy.</p><ul><li><Check size={16} />Private gated community</li><li><Check size={16} />Reliable Wi-Fi and workspace</li><li><Check size={16} />Self check-in guidance after confirmation</li><li><Check size={16} />Free roadside parking</li></ul><button className="secondary" onClick={() => setBookingStep(1)}>Check dates and rate <ArrowRight size={15} /></button></div></section><section className="guest-notes" id="reviews"><span className="eyebrow">Guest notes</span><div className="quote-score"><b>4.98</b><span>{Array.from({ length: 5 }).map((_, index) => <Star key={index} size={16} fill="currentColor" />)}</span><small>Airbnb reviews · verified 24 Aug 2026</small></div><blockquote>“The space felt carefully prepared and the host communication was genuinely helpful.”</blockquote><a href="https://www.airbnb.com/rooms/1523827999359515793" target="_blank" rel="noreferrer">View listing and current Airbnb reviews <ArrowRight size={14} /></a></section><footer className="guest-footer"><div><Mark /><b>Cascade Hideaway</b><span>Hotel Comfort. Home Warmth.</span></div><span>Questions before booking? <a href="mailto:cascadereservations@gmail.com">cascadereservations@gmail.com</a></span></footer></> : <BookingJourney step={bookingStep} setStep={setBookingStep} />
  return <div className="guest-shell">{body}<button className="suite-link booking-link" onClick={() => onProduct('cleaner')}>See the cleaner readiness flow <ArrowRight size={15} /></button></div>
}

function BookingJourney({ step, setStep }: { step: number; setStep: (step: number) => void }) {
  useLayoutEffect(() => {
    document.querySelectorAll<HTMLButtonElement>('button').forEach((button) => {
      if (!button.getAttribute('aria-label') && !button.textContent?.trim()) button.setAttribute('aria-label', 'Calendar navigation')
    })
  }, [step])
  return <div className="journey"><header className="journey-head"><button onClick={() => setStep(0)}><ChevronLeft size={18} />Back to stay</button><div className="journey-brand"><Mark /><b>Cascade Hideaway</b></div><span><ShieldCheck size={15} />Secure request</span></header><main><div className="journey-steps"><span className={step >= 1 ? 'active' : ''}><b>1</b>Dates</span><i></i><span className={step >= 2 ? 'active' : ''}><b>2</b>Details</span><i></i><span className={step >= 3 ? 'active' : ''}><b>3</b>Payment review</span></div>{step === 1 && <section className="journey-grid"><div><span className="eyebrow">Step 1 of 3</span><h1>Choose your stay</h1><p>Availability is checked against the live booking calendar before you continue.</p><div className="journey-calendar"><div><button><ChevronLeft size={16} /></button><b>September 2026</b><button><ChevronRight size={16} /></button></div><div className="journey-week"><span>M</span><span>T</span><span>W</span><span>T</span><span>F</span><span>S</span><span>S</span></div><div className="journey-days">{Array.from({ length: 30 }, (_, index) => index + 1).map((day) => <button key={day} className={[5, 6, 7].includes(day) ? 'selected' : [12, 13, 14, 15, 21, 22].includes(day) ? 'unavailable' : ''} disabled={[12, 13, 14, 15, 21, 22].includes(day)}>{day}</button>)}</div></div><div className="guest-count"><span>Guests</span><button><Users size={17} />2 guests <ChevronDown size={15} /></button></div><button className="primary full" onClick={() => setStep(2)}>Continue to guest details <ArrowRight size={16} /></button></div><BookingSummary /></section>}{step === 2 && <section className="journey-grid"><div><span className="eyebrow">Step 2 of 3</span><h1>Your details</h1><p>We ask only for what is needed to confirm and support your stay.</p><div className="form-grid"><label>Full name<input placeholder="Your name" defaultValue="Maria Reyes" /></label><label>Mobile number<input placeholder="09XX XXX XXXX" /></label><label className="wide">Email address<input type="email" placeholder="you@example.com" /></label><label className="wide">Special request <small>Optional</small><textarea placeholder="Tell us anything that would make arrival easier."></textarea></label></div><div className="privacy-copy"><LockKeyhole size={15} />Your information is used only to manage this reservation and send stay-related communication.</div><button className="primary full" onClick={() => setStep(3)}>Review payment options <ArrowRight size={16} /></button></div><BookingSummary /></section>}{step === 3 && <section className="journey-grid"><div><span className="eyebrow">Step 3 of 3</span><h1>Secure your dates</h1><p>Select a payment option. Your booking is confirmed only after availability and payment are verified.</p><div className="payment-options"><button className="selected"><Banknote size={20} /><span><b>50% reservation fee</b><small>₱2,670 now · remaining balance at check-in</small></span><CheckCircle2 size={18} /></button><button><WalletCards size={20} /><span><b>Pay in full</b><small>₱5,340 now · no balance at check-in</small></span></button></div><div className="payment-assurance"><ShieldCheck size={19} /><div><b>How confirmation works</b><p>Send through your chosen method, upload the receipt, then we match it with bank evidence and availability. A named team member confirms the booking and sends your stay details.</p></div></div><button className="primary full" onClick={() => setStep(4)}>Get payment instructions <ArrowRight size={16} /></button></div><BookingSummary /></section>}{step === 4 && <section className="confirmation"><span><CheckCircle2 size={32} /></span><Pill tone="good">Request prepared</Pill><h1>Almost there, Maria.</h1><p>Your dates are held while you complete the payment instructions. Uploading a receipt creates evidence for review; it does not automatically mark payment as received.</p><div><b>What happens next</b><ol><li>Complete the chosen payment method.</li><li>Upload a clear receipt or transfer confirmation.</li><li>We verify payment and availability, then send your confirmed stay details.</li></ol></div><button className="primary" onClick={() => setStep(0)}>Return to Cascade Hideaway</button></section>}</main></div>
}

function BookingSummary() { return <aside className="booking-summary"><img src={propertyImage} alt="Cascade Hideaway interior" /><div><span className="eyebrow">Your stay</span><h2>Cascade Hideaway</h2><p>Sep 5–8, 2026 · 3 nights · 2 guests</p></div><dl><div><dt>3 nights × ₱1,780</dt><dd>₱5,340</dd></div><div><dt>Cleaning fee</dt><dd>Included</dd></div><div className="total"><dt>Total</dt><dd>₱5,340</dd></div></dl><p className="summary-note"><BadgeCheck size={15} />No hidden booking-engine fee. Final confirmation follows verified payment and availability.</p></aside> }

export default function CompleteApp() {
  const [product, setProduct] = useState<Product>('dashboard')
  useLayoutEffect(() => {
    document.querySelectorAll<HTMLButtonElement>('button').forEach((button) => {
      if (!button.getAttribute('aria-label') && !button.textContent?.trim()) button.setAttribute('aria-label', 'Calendar navigation')
    })
  })
  return <div id="top" className="mockup-suite"><SuiteHeader product={product} onProduct={setProduct} />{product === 'dashboard' && <Dashboard onProduct={setProduct} />}{product === 'cleaner' && <CleanerMockup onProduct={setProduct} />}{product === 'booking' && <BookingMockup onProduct={setProduct} />}</div>
}
